from __future__ import annotations
from pathlib import Path
from time import perf_counter
from pydantic import BaseModel,ConfigDict
from .native_xref import DWGNativeXrefResolver
from ..pipeline import CADToCBIMPipeline
from ..ifc import IFCBridge

class DWGPipelineResult(BaseModel):
    model_config=ConfigDict(arbitrary_types_allowed=True)
    diagnostics:object
    xref_missing:list[str]
    canonical_document:object
    topology:object
    project:object
    ifc_path:str|None=None
    ifc_sanity:dict|None=None
    timings:dict[str,float]={}

class DWGToCBIMPipeline:
    def __init__(self, importer, *, cad_pipeline=None, ifc_bridge=None):
        self.importer=importer; self.cad_pipeline=cad_pipeline or CADToCBIMPipeline(); self.ifc_bridge=ifc_bridge or IFCBridge()
    @staticmethod
    def _emit(progress,stage,status,elapsed=None,**detail):
        if progress: progress(stage,status,elapsed,detail)
    def run(self,source:str|Path,*,resolve_xrefs:bool=True,export_ifc:str|Path|None=None,progress=None,**kwargs):
        source=Path(source); timings={}
        t=perf_counter();self._emit(progress,'dwg_import','start');base=self.importer.read_result(source);timings['dwg_import']=perf_counter()-t;self._emit(progress,'dwg_import','done',timings['dwg_import'],entities=len(base.document.entities),coverage=getattr(base.diagnostics,'coverage',None))
        missing=[];document=base.document
        if resolve_xrefs and base.xrefs:
            t=perf_counter();self._emit(progress,'xref','start');document,missing,_=DWGNativeXrefResolver(self.importer).compose(source);timings['xref']=perf_counter()-t;self._emit(progress,'xref','done',timings['xref'],missing=len(missing))
        stage_times={}
        def cad_progress(stage,status,elapsed,detail):
            if status=='done' and elapsed is not None: stage_times[stage]=elapsed
            self._emit(progress,stage,status,elapsed,**detail)
        cad,topo,project=self.cad_pipeline.run(document,progress=cad_progress,**kwargs);timings.update(stage_times)
        ifc_path=None; sanity=None
        if export_ifc is not None:
            t=perf_counter();self._emit(progress,'ifc_export','start');target=self.ifc_bridge.export(project,export_ifc); ifc_path=str(target); sanity=self.ifc_bridge.sanity_check(target);timings['ifc_export']=perf_counter()-t;self._emit(progress,'ifc_export','done',timings['ifc_export'],entity_count=(sanity or {}).get('entity_count',0))
        return DWGPipelineResult(diagnostics=base.diagnostics,xref_missing=missing,canonical_document=cad,topology=topo,project=project,ifc_path=ifc_path,ifc_sanity=sanity,timings=timings)
